 const string Folder="Assets/Recoil3D/ForecourtServiceYard",Marker="Station rear equipment yard and matching woodland - editable";
 static Material brick,concrete,steel,rust,dark,earth,asphalt,bark,leaves,farLeaves;static Mesh cone;static MeshRenderer hill;
 static T[] All<T>(Scene s)where T:Component{return s.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<T>(true)).ToArray();}
 static Transform G(Transform p,string n,Vector3 at){var t=new GameObject(n).transform;t.SetParent(p,false);t.position=at;return t;}
 static Transform B(Transform p,string n,Vector3 at,Vector3 size,Material m,PrimitiveType type=PrimitiveType.Cube){var t=GameObject.CreatePrimitive(type).transform;t.name=n;t.SetParent(p,false);t.position=at;t.localScale=size;Object.DestroyImmediate(t.GetComponent<Collider>());t.GetComponent<Renderer>().sharedMaterial=m;return t;}
 static Transform Rod(Transform p,string n,Vector3 a,Vector3 b,float r,Material m){var t=B(p,n,(a+b)*.5f,new Vector3(r*2,(a-b).magnitude*.5f,r*2),m,PrimitiveType.Cylinder);t.rotation=Quaternion.FromToRotation(Vector3.up,b-a);return t;}
 static Material Mat(string n,Color c){string path=Folder+"/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Recoil/3D/Weathered Surface"));AssetDatabase.CreateAsset(m,path);}m.color=c;m.enableInstancing=true;m.SetFloat("_Glossiness",.08f);m.SetFloat("_Weathering",.7f);EditorUtility.SetDirty(m);return m;}
 static float Ground(Vector3 p){if(!hill)return p.y;var mesh=hill.GetComponent<MeshFilter>().sharedMesh;var v=mesh.vertices;var tri=mesh.triangles;float highest=0;for(int i=0;i<tri.Length;i+=3){var a=hill.transform.TransformPoint(v[tri[i]]);var b=hill.transform.TransformPoint(v[tri[i+1]]);var c=hill.transform.TransformPoint(v[tri[i+2]]);float det=(b.z-c.z)*(a.x-c.x)+(c.x-b.x)*(a.z-c.z);if(Mathf.Abs(det)<.00001f)continue;float u=((b.z-c.z)*(p.x-c.x)+(c.x-b.x)*(p.z-c.z))/det,w=((c.z-a.z)*(p.x-c.x)+(a.x-c.x)*(p.z-c.z))/det,q=1-u-w;if(u>=-.0001f&&w>=-.0001f&&q>=-.0001f)highest=Mathf.Max(highest,u*a.y+w*b.y+q*c.y);}return highest-.04f;}
 static void Tree(Transform p,Vector3 at,float h,int seed,bool far){at.y=Ground(at);var t=G(p,"Spruce matching right-hand forest "+seed,at);Rod(t,"Trunk",at,at+Vector3.up*h*.76f,.09f,bark);for(int i=0;i<3;i++){var c=G(t,"Uneven spruce crown",at+new Vector3((seed%3-1)*.08f,h*(.38f+i*.19f),0));c.localScale=new Vector3(h*(.58f-i*.10f),h*.47f,h*(.53f-i*.09f));c.rotation=Quaternion.Euler(0,seed*37,0);c.gameObject.AddComponent<MeshFilter>().sharedMesh=cone;var mr=c.gameObject.AddComponent<MeshRenderer>();mr.sharedMaterial=far?farLeaves:leaves;mr.shadowCastingMode=ShadowCastingMode.Off;}}
 static Mesh SaveMesh(string name,Mesh mesh){string path=Folder+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);return old;}mesh.name=name;AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static void Batch(Transform root,string id){int i=0;var filters=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&f.GetComponent<MeshRenderer>()).ToArray();foreach(var group in filters.GroupBy(f=>f.GetComponent<MeshRenderer>().sharedMaterial)){var list=group.ToArray();if(list.Length<2)continue;var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(list.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=root.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray(),true,true);var t=G(root,"Static detail - "+group.Key.name,root.position);t.gameObject.AddComponent<MeshFilter>().sharedMesh=SaveMesh(id+"-"+(i++),mesh);t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=group.Key;foreach(var f in list){Object.DestroyImmediate(f.GetComponent<MeshRenderer>());Object.DestroyImmediate(f);}}}
 static void Fence(Transform root,Vector3 a,Vector3 b,bool concreteBottom){var g=G(root,"Weathered yard boundary",a);int spans=Mathf.CeilToInt(Vector3.Distance(a,b)/2.4f);for(int i=0;i<=spans;i++){Vector3 at=Vector3.Lerp(a,b,i/(float)spans);B(g,"Uneven concrete fence post",at+Vector3.up*.92f,new Vector3(.15f,1.84f,.15f),concrete);if(i==spans)continue;Vector3 next=Vector3.Lerp(a,b,(i+1)/(float)spans);if(concreteBottom){var panel=B(g,"Low stained precast fence panel",(at+next)*.5f+Vector3.up*.32f,new Vector3((at-next).magnitude-.12f,.64f,.10f),concrete);panel.rotation=Quaternion.LookRotation(Vector3.Cross(next-at,Vector3.up));}
   foreach(float y in new[]{.73f,1.7f})Rod(g,"Rusting fence tension wire",at+Vector3.up*y,next+Vector3.up*y,.012f,rust);
   for(int j=0;j<10;j++){float u=j/10f;var lo=Vector3.Lerp(at,next,u)+Vector3.up*.78f;var hi=Vector3.Lerp(at,next,Mathf.Min(1,u+.17f))+Vector3.up*1.65f;Rod(g,"Sparse diagonal wire mesh",lo,hi,.005f,steel);}}
 }
 static void Yard(Transform root){var g=G(root,"Low brick maintenance and equipment building",new Vector3(-24,0,24));
  B(g,"Equipment room masonry",new Vector3(-24,1.65f,24),new Vector3(8,3.3f,5.5f),brick);B(g,"Overhanging dark flat roof",new Vector3(-24,3.38f,24),new Vector3(8.4f,.18f,5.9f),dark);B(g,"Weathered footing",new Vector3(-24,.16f,24),new Vector3(8.12f,.32f,5.62f),concrete);
  B(g,"Dark door recess",new Vector3(-25.1f,1.13f,21.205f),new Vector3(1.3f,2.26f,.065f),dark);B(g,"Closed equipment room steel door",new Vector3(-25.1f,1.11f,21.155f),new Vector3(1.16f,2.18f,.06f),steel);foreach(float x in new[]{-25.74f,-24.46f})B(g,"Door jamb fixed to brick",new Vector3(x,1.14f,21.12f),new Vector3(.085f,2.30f,.16f),rust);B(g,"Door lintel",new Vector3(-25.1f,2.3f,21.12f),new Vector3(1.4f,.09f,.16f),rust);B(g,"Old door handle",new Vector3(-24.67f,1.1f,21.09f),new Vector3(.035f,.18f,.07f),steel);
  B(g,"Small dirty high window",new Vector3(-21.6f,2.5f,21.185f),new Vector3(1.7f,.58f,.10f),dark);for(int i=0;i<4;i++)B(g,"High window divider",new Vector3(-22.36f+i*.51f,2.5f,21.12f),new Vector3(.045f,.60f,.05f),steel);B(g,"High window sill",new Vector3(-21.6f,2.18f,21.10f),new Vector3(1.84f,.09f,.20f),concrete);
  for(int i=0;i<6;i++)B(g,"Louvred equipment vent",new Vector3(-27.1f,1.5f+i*.10f,21.15f),new Vector3(.6f,.045f,.08f),steel);
  var vents=G(root,"Fuel tank vents and ground inspection covers",new Vector3(-29,0,19));for(int i=0;i<3;i++){var a=new Vector3(-29.7f+i*.48f,.15f,19.6f);var top=a+Vector3.up*(3.9f+i*.38f);Rod(vents,"Underground tank vent riser",a,top,.045f,steel);Rod(vents,"Bent weather-protected vent outlet",top,top+new Vector3(.25f,0,0),.045f,steel);Rod(vents,"Downturned vent end",top+new Vector3(.25f,0,0),top+new Vector3(.25f,-.20f,0),.045f,steel);B(vents,"Vent pipe base fixing",a,new Vector3(.18f,.10f,.18f),rust);}
  for(int i=0;i<3;i++){var at=new Vector3(-30+i*1.35f,.025f,16.7f);B(vents,"Sunken underground tank inspection cover",at,new Vector3(.68f,.035f,.68f),steel);B(vents,"Filling point flush cap",at+new Vector3(.12f,.035f,0),new Vector3(.16f,.04f,.16f),rust,PrimitiveType.Cylinder);}
  Fence(root,new Vector3(-35,0,14.5f),new Vector3(-20,0,14.5f),true);Fence(root,new Vector3(-15.5f,0,14.5f),new Vector3(-10,0,16.5f),true);Fence(root,new Vector3(-35,0,14.5f),new Vector3(-35,0,29),false);
  var gate=G(root,"Closed repaired wire gate on disused service road",new Vector3(-17.75f,0,14.5f));foreach(float x in new[]{-20f,-15.5f})Rod(gate,"Gate hinge post",new Vector3(x,0,14.5f),new Vector3(x,2.1f,14.5f),.07f,steel);foreach(float y in new[]{.2f,1.85f})Rod(gate,"Repaired gate crossmember",new Vector3(-19.9f,y,14.5f),new Vector3(-15.6f,y,14.5f),.035f,steel);for(int i=0;i<10;i++)Rod(gate,"Gate vertical mesh wire",new Vector3(-19.8f+i*.45f,.2f,14.5f),new Vector3(-19.8f+i*.45f,1.85f,14.5f),.008f,rust);Rod(gate,"Old diagonal gate repair",new Vector3(-19.9f,.2f,14.5f),new Vector3(-15.6f,1.85f,14.5f),.032f,rust);
  var road=G(root,"Old service track bends behind trees",Vector3.zero);var points=new[]{new Vector3(-17.75f,0,13),new Vector3(-16,0,24),new Vector3(-18,0,34),new Vector3(-23,0,43)};for(int i=0;i<points.Length-1;i++){var a=points[i];var b=points[i+1];var t=B(road,"Faded rear access asphalt",(a+b)*.5f+Vector3.up*.008f,new Vector3(i==2?2.1f:3.0f,.025f,(b-a).magnitude+.1f),asphalt);t.rotation=Quaternion.LookRotation(b-a);}
  var stuff=G(root,"Old maintenance supplies clustered at wall",new Vector3(-28,0,22));B(stuff,"Locked old oil and tool cabinet",new Vector3(-27.3f,.65f,20.65f),new Vector3(.95f,1.3f,.43f),steel);for(int i=0;i<4;i++){var t=B(stuff,"Old tyre against side wall",new Vector3(-28.3f,.27f+i*.13f,22.0f+i*.05f),new Vector3(.64f,.13f,.64f),dark,PrimitiveType.Cylinder);t.rotation=Quaternion.Euler(6*i,0,4*i);}B(stuff,"Half buried cracked shield by ditch",new Vector3(-13.3f,.045f,16.8f),new Vector3(.50f,.055f,.82f),dark).rotation=Quaternion.Euler(0,28,-5);
  for(int i=0;i<25;i++){var at=new Vector3(-35+i*1.05f,.055f,14.5f+Mathf.Sin(i*2.7f)*.55f);B(root,"Grass clump at neglected fence footing",at,new Vector3(.28f,.10f,.30f),leaves,PrimitiveType.Sphere);}
 }
 public static string Apply(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop Play first");var scene=SceneManager.GetSceneByPath("Assets/Scenes/3D/RecoilPrototype.unity");if(!scene.isLoaded)throw new Exception("Open outdoor scene first");var w=All<RecoilPrototype>(scene).Single();if(w.transform.Find(Marker))return "Already applied";
  string backup="Backups/ForecourtServiceYard/"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity";Directory.CreateDirectory(Path.GetDirectoryName(backup));EditorSceneManager.SaveScene(scene,backup,true);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();
  brick=Mat("Soot stained utility brick",new Color(.25f,.245f,.21f));var architectural=Shader.Find("Recoil/3D/Architectural Surface");if(architectural)brick.shader=architectural;concrete=Mat("Aged low fence concrete",new Color(.24f,.26f,.23f));steel=Mat("Weathered station grey green metal",new Color(.16f,.21f,.19f));rust=Mat("Old fence and pipe rust",new Color(.19f,.105f,.055f));dark=Mat("Unlit equipment recesses",new Color(.035f,.047f,.043f));asphalt=Mat("Disused service lane asphalt",new Color(.095f,.11f,.105f));earth=Mat("Neglected service yard earth",new Color(.12f,.135f,.105f));
  bark=AssetDatabase.LoadAssetAtPath<Material>("Assets/Recoil3D/Residential/Materials/Weathered timber.mat");leaves=AssetDatabase.LoadAssetAtPath<Material>("Assets/Recoil3D/Residential/Materials/Nearby spruce and birch leaves.mat");farLeaves=AssetDatabase.LoadAssetAtPath<Material>("Assets/Recoil3D/Residential/Materials/Distant tree silhouettes.mat");cone=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Recoil3D/Residential/Meshes/Spruce cone.asset");if(!bark||!leaves||!farLeaves||!cone)throw new Exception("Right forest reference missing");
  var colliders=All<Collider2D>(scene).Select(c=>c.GetInstanceID()+"|"+c.bounds).ToArray();var routes=All<RecoilDoor>(scene).Select(d=>d.name+"|"+d.destinationScene+"|"+d.destinationSpawn+"|"+d.transform.position).ToArray();var root=G(w.transform,Marker,Vector3.zero);Yard(root);
  var woodland=G(root,"Left forest - same spruce family as factory right",Vector3.zero);var country=w.transform.Find("Opening - roadside service station/Countryside - low hills woods and mining settlement");hill=country.GetComponentsInChildren<MeshRenderer>(true).Single(r=>r.name=="Static detail - Near countryside atmosphere");int count=0;
  // The old distant crowns were combined with village roofs. Retain the roofs and only remove tree triangles at Z>44.
  var original=country.GetComponentsInChildren<MeshRenderer>(true).Single(r=>r.name=="Static detail - Dark tree line");var oldFilter=original.GetComponent<MeshFilter>();var source=oldFilter.sharedMesh;var keep=new List<int>();var verts=source.vertices;var triangles=source.triangles;for(int i=0;i<triangles.Length;i+=3){float z=(original.transform.TransformPoint(verts[triangles[i]]).z+original.transform.TransformPoint(verts[triangles[i+1]]).z+original.transform.TransformPoint(verts[triangles[i+2]]).z)/3;if(z<44)keep.AddRange(new[]{triangles[i],triangles[i+1],triangles[i+2]});}var retained=Object.Instantiate(source);retained.SetTriangles(keep,0);retained.RecalculateBounds();oldFilter.sharedMesh=SaveMesh("Preserved distant village roofs",retained);EditorUtility.SetDirty(oldFilter);
  foreach(var t in country.Cast<Transform>().Where(t=>t.name=="Mixed woodland tree").ToArray()){Tree(woodland,t.position,4.8f+(count%4)*.65f,100+count,true);count++;}
  foreach(var t in w.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Sparse neglected roadside tree")).ToArray()){foreach(var r in t.GetComponentsInChildren<Renderer>(true))r.enabled=false;Tree(woodland,t.position,4.0f+(count%3)*.5f,100+count,false);count++;}
  for(int i=0;i<13;i++){float x=-42+i*2.9f,z=31+(i%3)*4.5f;if(x> -25&&x< -18)z+=8;Tree(woodland,new Vector3(x,0,z),4.5f+(i%4)*.75f,300+i,i%3==2);}
  // Avoid an evenly filled skyline: a few taller silhouettes and gaps reveal the existing hills.
  Batch(woodland,"matching-left-woodland");var art=G(root,"Static equipment yard geometry",Vector3.zero);foreach(Transform child in root.Cast<Transform>().Where(t=>t!=woodland&&t!=art).ToArray())child.SetParent(art,true);Batch(art,"station-yard");
  if(root.GetComponentsInChildren<Collider>(true).Length+root.GetComponentsInChildren<Collider2D>(true).Length!=0)throw new Exception("Background props add blockers");if(!colliders.SequenceEqual(All<Collider2D>(scene).Select(c=>c.GetInstanceID()+"|"+c.bounds)))throw new Exception("Collision changed");if(!routes.SequenceEqual(All<RecoilDoor>(scene).Select(d=>d.name+"|"+d.destinationScene+"|"+d.destinationSpawn+"|"+d.transform.position)))throw new Exception("Doors changed");
  EditorSceneManager.MarkSceneDirty(scene);AssetDatabase.SaveAssets();if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");Directory.CreateDirectory("output/forecourt-service-yard");string report="PASS equipment building, vent risers, inspection covers, fence, closed gate and old curving service road. Replaced "+count+" left-side trees and added13 matching rear trees using right forest mesh/materials. Static geometry batched into "+root.GetComponentsInChildren<MeshRenderer>().Length+" renderers, no new lights, no new collision; door routes unchanged. Backup: "+backup;File.WriteAllText("output/forecourt-service-yard/verification.txt",report);return report;
 }
 public static string GroundExistingForest(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop Play first");var scene=SceneManager.GetSceneByPath("Assets/Scenes/3D/RecoilPrototype.unity");var root=All<Transform>(scene).Single(t=>t.name==Marker);var old=root.Find("Left forest - same spruce family as factory right");var specs=old.Cast<Transform>().Where(t=>t.name.StartsWith("Spruce matching")).Select(t=>new{position=t.position,height=t.Find("Uneven spruce crown").localScale.y/.47f,seed=int.Parse(t.name.Split(' ').Last())}).ToArray();bark=AssetDatabase.LoadAssetAtPath<Material>("Assets/Recoil3D/Residential/Materials/Weathered timber.mat");leaves=AssetDatabase.LoadAssetAtPath<Material>("Assets/Recoil3D/Residential/Materials/Nearby spruce and birch leaves.mat");farLeaves=AssetDatabase.LoadAssetAtPath<Material>("Assets/Recoil3D/Residential/Materials/Distant tree silhouettes.mat");cone=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Recoil3D/Residential/Meshes/Spruce cone.asset");hill=All<MeshRenderer>(scene).Single(r=>r.name=="Static detail - Near countryside atmosphere");Object.DestroyImmediate(old.gameObject);var woodland=G(root,"Left forest - same spruce family as factory right",Vector3.zero);foreach(var a in specs)Tree(woodland,a.position,a.height,a.seed,a.position.z>40||a.seed>=300&&(a.seed-300)%3==2);Batch(woodland,"matching-left-woodland");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return "Grounded "+specs.Length+" matching trees on actual hill mesh";}
